import { chromium } from 'playwright'

const base = process.env.SHOT_BASE || 'http://127.0.0.1:8092'
const out = process.env.SHOT_OUT || 'C:/Users/Administrator/AppData/Local/Temp/credit-shot.png'

const browser = await chromium.launch()
const page = await browser.newPage({ viewport: { width: 1920, height: 1080 }, deviceScaleFactor: 2 })
page.on('console', (m) => { if (m.type() === 'error') console.log('CONSOLE-ERR:', m.text()) })

// allow page to render without backend
await page.route('**/api/v3.0/**', (r) => r.fulfill({ status: 200, contentType: 'application/json', body: JSON.stringify({ code: 200, rows: [], data: {}, total: 0 }) }))
await page.route('**/api/v2.0/**', (r) => r.fulfill({ status: 200, contentType: 'application/json', body: JSON.stringify({ code: 200, rows: [], data: [], total: 0 }) }))
await page.route('**/portal/public/externalInfo/publicNotice/page*', (r) => r.fulfill({ status: 200, contentType: 'application/json', body: JSON.stringify({ code: 200, rows: [], total: 0 }) }))
await page.route('**/system/platformConfig/getInfo*', (r) => r.fulfill({ status: 200, contentType: 'application/json', body: JSON.stringify({ code: 200, data: { projectId: 'e2e', region: '江苏省苏州市', buttonDefaultColor: '' } }) }))

await page.goto(`${base}/#/UnifiedLogin?portal=agency-credit`, { waitUntil: 'domcontentloaded' })
await page.waitForTimeout(1500)

// wait skeleton gone
const skel = page.locator('.portal-skeleton')
try { await skel.waitFor({ state: 'detached', timeout: 8000 }) } catch {}

const table = page.locator('.portal-table-panel')
await table.waitFor({ state: 'visible', timeout: 8000 })

// read the first credit cell text + overflow metric
const info = await page.evaluate(() => {
  const cells = document.querySelectorAll('.portal-table tbody tr td')
  const result = []
  document.querySelectorAll('.portal-table tbody tr').forEach((tr) => {
    const tds = tr.querySelectorAll('td')
    if (tds.length >= 2) {
      const codeTd = tds[1]
      const span = codeTd.querySelector('.credit-code')
      result.push({
        text: (span ? span.textContent : codeTd.textContent).trim(),
        tdWidth: codeTd.clientWidth,
        scrollWidth: codeTd.scrollWidth,
        spanScrollWidth: span ? span.scrollWidth : null,
      })
    }
  })
  return result
})
console.log('CREDIT CELLS:', JSON.stringify(info, null, 2))

await table.screenshot({ path: out })
console.log('SHOT:', out)
await browser.close()

